SELECT  FROM model_version
WHERE model_id = #{modelId} AND version = #{version}
LIMIT 1

SELECT  FROM model_version
WHERE checksum = #{checksum} AND status = 'ready' AND model_id = #{modelId}
LIMIT 1

SELECT  FROM model_version
WHERE model_id = #{modelId}
ORDER BY created_at DESC

mapper.update:
UPDATE model_version
version = #{version}, storage_path = #{storagePath}, file_size = #{fileSize}, checksum = #{checksum}, status = #{status}, config = CAST(#{config} AS JSONB), updated_at = NOW()
WHERE id = #{id}
